<?php
session_start(); include "../config/koneksi.php";
if (!isset($_SESSION['role']) || $_SESSION['role'] !== 'user') { header("location:../login.php"); exit; }
$kategori_id = isset($_GET['kategori']) ? max(0, (int)$_GET['kategori']) : 0;
$keyword = trim($_GET['keyword'] ?? '');
$sort = $_GET['sort'] ?? 'terbaru';
$sortOptions = ['terbaru'=>'buku.id_buku DESC','termurah'=>'buku.harga ASC, buku.id_buku DESC','termahal'=>'buku.harga DESC, buku.id_buku DESC','az'=>'buku.judul_buku ASC'];
$orderBy = $sortOptions[$sort] ?? $sortOptions['terbaru'];
$kategori = mysqli_query($conn, "SELECT * FROM kategori ORDER BY nama_kategori ASC");
$where=[];
if($kategori_id>0){$where[]="buku.id_kategori=$kategori_id";}
if($keyword!==''){$escaped=mysqli_real_escape_string($conn,$keyword);$where[]="(buku.judul_buku LIKE '%$escaped%' OR buku.penulis LIKE '%$escaped%')";}
$sql = "SELECT buku.*, kategori.nama_kategori FROM buku LEFT JOIN kategori ON buku.id_kategori=kategori.id_kategori" . ($where?' WHERE '.implode(' AND ',$where):'') . " ORDER BY " . $orderBy;
$data=mysqli_query($conn,$sql);
?>
