<main class="content-user catalog-page"><form class="catalog-toolbar" method="GET"><div class="search-field"><input aria-label="Cari judul atau penulis" name="keyword" value="<?= htmlspecialchars($keyword,ENT_QUOTES,'UTF-8') ?>" placeholder="Cari judul atau penulis..."><button type="submit" aria-label="Cari buku">⌕</button></div><select name="kategori" aria-label="Filter kategori"><option value="0">Semua Kategori</option><?php if($kategori): while($k=mysqli_fetch_assoc($kategori)): ?><option value="<?= (int)$k['id_kategori'] ?>" <?= $kategori_id===(int)$k['id_kategori']?'selected':'' ?>><?= htmlspecialchars($k['nama_kategori'],ENT_QUOTES,'UTF-8') ?></option><?php endwhile; endif; ?></select><select name="sort" aria-label="Urutkan buku"><option value="terbaru" <?= $sort==='terbaru'?'selected':'' ?>>Terbaru</option><option value="termurah" <?= $sort==='termurah'?'selected':'' ?>>Harga Termurah</option><option value="termahal" <?= $sort==='termahal'?'selected':'' ?>>Harga Termahal</option><option value="az" <?= $sort==='az'?'selected':'' ?>>Judul A–Z</option></select><button class="btn filter-btn" type="submit">Terapkan</button><?php if($kategori_id||$keyword!==''||$sort!=='terbaru'): ?><a class="clear-filter" href="katalog.php">Reset</a><?php endif; ?></form>
<div class="result-note"><?= $data?mysqli_num_rows($data):0 ?> BUKU DITEMUKAN</div><div class="book-container"><?php if($data && mysqli_num_rows($data)>0): while($row=mysqli_fetch_assoc($data)): $detailUrl='detail_buku.php?id='.(int)$row['id_buku']; ?><article class="book-card"><a class="cover-wrap" href="<?= $detailUrl ?>"><img loading="lazy" src="../images/buku/<?= rawurlencode($row['gambar']??'') ?>" alt="Sampul <?= htmlspecialchars($row['judul_buku'],ENT_QUOTES,'UTF-8') ?>"></a><div class="book-meta"><span class="book-category"><?= htmlspecialchars($row['nama_kategori']??'Koleksi',ENT_QUOTES,'UTF-8') ?></span><h3><a href="<?= $detailUrl ?>"><?= htmlspecialchars($row['judul_buku'],ENT_QUOTES,'UTF-8') ?></a></h3><p class="author"><?= htmlspecialchars($row['penulis']??'',ENT_QUOTES,'UTF-8') ?></p><p class="book-stock"><?= (int)$row['stok']>0?'Tersedia · '.(int)$row['stok'].' stok':'Stok habis' ?></p><div class="book-bottom"><strong>Rp <?= number_format((float)$row['harga'],0,',','.') ?></strong><a class="mini-link" href="<?= $detailUrl ?>">Detail ↗</a></div></div></article><?php endwhile; else: ?><div class="empty-state"><span>✧</span><h3>Tidak ada buku di rak ini.</h3><p>Coba pilih kategori berbeda atau gunakan kata pencarian lain.</p><a href="katalog.php" class="btn" style="margin-top:20px">Lihat Semua Koleksi</a></div><?php endif; ?></div></main>
